import { Group, Mesh, MeshStandardNodeMaterial, PlaneGeometry, ExtrudeGeometry, Shape } from 'three/webgpu';
import { uniform, normalWorld, cameraPosition, positionWorld, normalize, dot, saturate, sub, mix, vec3, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Button shape ---
  const w = 2.6, h = 0.68, r = 0.08;
  const shape = new Shape();
  shape.moveTo(-w/2 + r, -h/2);
  shape.lineTo(w/2 - r, -h/2);
  shape.quadraticCurveTo(w/2, -h/2, w/2, -h/2 + r);
  shape.lineTo(w/2, h/2 - r);
  shape.quadraticCurveTo(w/2, h/2, w/2 - r, h/2);
  shape.lineTo(-w/2 + r, h/2);
  shape.quadraticCurveTo(-w/2, h/2, -w/2, h/2 - r);
  shape.lineTo(-w/2, -h/2 + r);
  shape.quadraticCurveTo(-w/2, -h/2, -w/2 + r, -h/2);

  const extrudeSettings = {
    depth: 0.01,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.01,
    bevelSegments: 1,
  };
  const geom = new ExtrudeGeometry(shape, extrudeSettings);
  // The front face of the extrusion is at z = depth + bevelThickness = 0.02 after extrusion.
  // Shift so that front face is at z = 0.
  geom.translate(0, 0, -0.02);

  // --- Gradient texture ---
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 135; // matches aspect ratio 2.6/0.68 ≈ 3.8235, 512/135 ≈ 3.7926 close enough
  const ctx2 = canvas.getContext('2d');
  // Fill gradient
  const grad = ctx2.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, '#ff4450');
  grad.addColorStop(0.55, '#ff2a38');
  grad.addColorStop(1, '#c1121f');
  ctx2.fillStyle = grad;
  ctx2.fillRect(0, 0, canvas.width, canvas.height);
  // Hard seam line at 50% height (0.5 * canvas.height)
  const seamY = Math.round(0.5 * canvas.height);
  ctx2.fillStyle = '#ff2a38';
  ctx2.fillRect(0, seamY, canvas.width, 1);
  const gradientTexture = new ctx.THREE.CanvasTexture(canvas);
  gradientTexture.wrapS = ctx.THREE.ClampToEdgeWrapping;
  gradientTexture.wrapT = ctx.THREE.ClampToEdgeWrapping;

  // --- Emissive uniform ---
  const emissiveIntensity = uniform(1.6);

  // --- Fresnel emissive node ---
  const viewDir = normalize(sub(cameraPosition, positionWorld));
  const fresnel = float(1).sub(saturate(dot(normalWorld, viewDir)));
  const emissiveColor = vec3(0x2a, 0x38, 0xff).mul(1/255); // #ff2a38 as normalized vec3
  const emissiveNode = mix(vec3(0), emissiveColor.mul(emissiveIntensity), fresnel);

  // --- Button material ---
  const mat = new MeshStandardNodeMaterial();
  mat.colorNode = gradientTexture;
  mat.roughnessNode = float(0.5);
  mat.metalnessNode = float(0.35);
  mat.clearcoatNode = float(0.22);
  mat.emissiveNode = emissiveNode;
  mat.needsUpdate = true;

  const btnMesh = new Mesh(geom, mat);
  btnMesh.castShadow = true;
  btnMesh.receiveShadow = true;
  group.add(btnMesh);

  // --- Contact shadow plane ---
  const shadowGeom = new PlaneGeometry(2.8, 0.76);
  const shadowMat = new ctx.THREE.MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.z = -0.08;
  shadowMesh.receiveShadow = false;
  group.add(shadowMesh);

  // --- Text creation helper ---
  function createText(content, opts, desiredWidth, yPos) {
    const text = ctx.fontAtlas.createText(content, opts);
    const textMesh = text.children[0]; // assume single child mesh
    if (textMesh) {
      const bbox = textMesh.geometry.boundingBox;
      if (bbox) {
        const textWidth = bbox.max.x - bbox.min.x;
        const scale = desiredWidth / textWidth;
        text.scale.set(scale, scale, 1);
      }
    }
    text.position.set(0, yPos, 0.01);
    group.add(text);
    return text;
  }

  // --- CTA label ---
  const labelDesiredWidth = 2.6 - 0.5; // 0.25 padding each side
  createText('BEGIN COMMISSION', {
    fontSize: 0.2,
    color: '#16161d',
    align: 'center',
    letterSpacing: 0.08,
  }, labelDesiredWidth, 0);

  // --- Caption ---
  const captionY = -0.34 - 0.25; // below button bottom
  createText('NO DEPOSIT REQUIRED', {
    fontSize: 0.09,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.12,
  }, labelDesiredWidth, captionY);

  // --- Initial scale for mount motion ---
  group.scale.set(1.04, 1.04, 1.04);

  // --- GSAP timeline for mount ---
  const mountTl = gsap.timeline();
  mountTl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto',
  });

  // --- Reference for hover/press ---
  let hoverTl = gsap.timeline({ paused: true });
  let pressTl = gsap.timeline({ paused: true });

  // --- Event handlers ---
  const handlers = {
    pointerenter: () => {
      hoverTl.clear();
      hoverTl = gsap.timeline();
      hoverTl.to(btnMesh.position, {
        z: 0.06,
        duration: 0.18,
        ease: 'power2.out',
      }, 0);
      hoverTl.to(emissiveIntensity, {
        value: 2.2,
        duration: 0.18,
        ease: 'power2.out',
      }, 0);
    },
    pointerleave: () => {
      hoverTl.reverse();
    },
    pointerdown: () => {
      pressTl.clear();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.2)',
        overwrite: 'auto',
      }, 0);
      pressTl.to(shadowMesh.scale, {
        x: 0.85, y: 0.85,
        duration: 0.12,
        ease: 'back.out(1.2)',
        overwrite: 'auto',
      }, 0);
    },
    pointerup: () => {
      pressTl.reverse();
      // Also reset shadow scale after reverse completes
    },
  };

  btnMesh.userData.handlers = handlers;

  // --- Cleanup ---
  const userDataCleanup = () => {
    mountTl.kill();
    hoverTl.kill();
    pressTl.kill();
    geom.dispose();
    mat.dispose();
    gradientTexture.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    // Dispose text geometries (if needed, but they are children of group)
    group.children.forEach(child => {
      if (child.isMesh) {
        child.geometry?.dispose();
        child.material?.dispose();
        if (child.material?.map) child.material.map.dispose();
      }
    });
  };
  group.userData.cleanup = userDataCleanup;

  return group;
}
